import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  radioCaptionClassName,
  radioGroupClassName,
  radioIndicatorClassName,
  radioItemClassName,
  radioRootClassName,
} from "./view";

export {
  radioCaptionClassName,
  radioGroupClassName,
  radioIndicatorClassName,
  radioItemClassName,
  radioRootClassName,
} from "./view";

export type RadioStyle = Readonly<Record<string, string>>;

export type GroupViewConfig = Readonly<{
  label: string;
  labelId: string;
  children: readonly Html[];
  name?: string | undefined;
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  className?: string | undefined;
  style?: RadioStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  value: string;
  selectedValue: string;
  onValueChange: ParentMessage;
  label: string;
  disabled?: boolean | undefined;
  required?: boolean | undefined;
  className?: string | undefined;
  style?: RadioStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  checked: boolean,
  disabled: boolean,
  required: boolean
) => [
  ...(checked
    ? [h.DataAttribute("checked", "")]
    : [h.DataAttribute("unchecked", "")]),
  ...(disabled ? [h.DataAttribute("disabled", "")] : []),
  ...(required ? [h.DataAttribute("required", "")] : []),
];

export const groupView = <ParentMessage>({
  label,
  labelId,
  children,
  name,
  disabled = false,
  required = false,
  className,
  style,
}: GroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "radiogroup"),
      h.Attribute("aria-labelledby", labelId),
      ...(name === undefined ? [] : [h.DataAttribute("name", name)]),
      ...(disabled ? [h.DataAttribute("disabled", "")] : []),
      ...(required ? [h.Attribute("aria-required", "true")] : []),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(radioGroupClassName, className)),
    ],
    [
      h.div([h.Id(labelId), h.Class(radioCaptionClassName)], [label]),
      ...children,
    ]
  );
};

export const itemView = <ParentMessage>({
  value,
  selectedValue,
  onValueChange,
  label,
  disabled = false,
  required = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();
  const checked = selectedValue === value;

  return h.label(
    [
      ...stateAttributes(h, checked, disabled, required),
      ...(disabled ? [] : [h.OnClick(onValueChange)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(radioItemClassName, className)),
    ],
    [
      h.span(
        [
          h.Attribute("role", "radio"),
          h.AriaLabel(label),
          h.Attribute("aria-checked", checked ? "true" : "false"),
          ...(disabled ? [h.Attribute("aria-disabled", "true")] : []),
          ...(required ? [h.Attribute("aria-required", "true")] : []),
          ...stateAttributes(h, checked, disabled, required),
          ...(disabled ? [] : [h.OnClick(onValueChange)]),
          h.Class(radioRootClassName),
        ],
        [
          h.span(
            [
              ...stateAttributes(h, checked, disabled, required),
              h.Class(radioIndicatorClassName),
            ],
            []
          ),
        ]
      ),
      h.span(disabled ? [] : [h.OnClick(onValueChange)], [label]),
    ]
  );
};

export const radioGroupClassName = "flex flex-col gap-3";

export const radioCaptionClassName = "text-sm font-medium text-gray-950";

export const radioItemClassName =
  "flex cursor-pointer items-center gap-2 text-sm text-gray-700 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const radioRootClassName =
  "flex h-4 w-4 shrink-0 items-center justify-center rounded-full border border-gray-300 bg-white text-white transition-colors data-[checked]:border-accent-600 data-[checked]:bg-accent-600 data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const radioIndicatorClassName =
  "h-1.5 w-1.5 rounded-full bg-current opacity-0 data-[checked]:opacity-100";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, expect, test } from "vitest";

import * as Radio from "./index";

const SelectedApple = m("SelectedApple", { value: S.String });
const Message = S.Union([SelectedApple]);
type Message = typeof Message.Type;

const view = (selectedValue: string): Html =>
  Radio.groupView<Message>({
    label: "Best apple",
    labelId: "best-apple-label",
    children: [
      Radio.itemView<Message>({
        value: "fuji-apple",
        selectedValue,
        label: "Fuji",
        onValueChange: SelectedApple({ value: "fuji-apple" }),
      }),
      Radio.itemView<Message>({
        value: "gala-apple",
        selectedValue,
        label: "Gala",
        onValueChange: SelectedApple({ value: "gala-apple" }),
      }),
    ],
  });

describe("Radio registry view", () => {
  test("renders Base UI group and radio checked state", () => {
    Scene.scene(
      {
        update: (_model: string, message: Message): readonly [string, []] => {
          expect(message._tag).toBe("SelectedApple");
          return [message.value, []];
        },
        view,
      },
      Scene.with("fuji-apple"),
      Scene.expect(Scene.role("radiogroup", { name: "Best apple" })).toExist(),
      Scene.expect(Scene.role("radio", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("radio", { name: "Gala" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.click(Scene.text("Gala")),
      Scene.expect(Scene.role("radio", { name: "Fuji" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.expect(Scene.role("radio", { name: "Gala" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });
});
